import hmac
import hashlib
import base64
import json
import time
import os
from typing import Optional, Dict, Tuple


class KeyStore:
    def __init__(self):
        self._keys: Dict[str, dict] = {}

    def register_key(self, kid: str, key_material: bytes, algorithm: str):
        self._keys[kid] = {
            'material': key_material,
            'algorithm': algorithm,
            'created_at': time.time()
        }

    def get_key(self, kid: str) -> Optional[dict]:
        return self._keys.get(kid)


class TokenService:
    SUPPORTED_ALGORITHMS = {'HS256', 'HS384', 'HS512', 'RS256'}

    def __init__(self, key_store: KeyStore):
        self._key_store = key_store
        self._revoked: set = set()
        self._issued_count = 0

    def _b64url_encode(self, data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

    def _b64url_decode(self, s: str) -> bytes:
        padding = 4 - len(s) % 4
        if padding != 4:
            s += '=' * padding
        return base64.urlsafe_b64decode(s)

    def _compute_signature(self, algorithm: str, key_material: bytes, message: bytes) -> bytes:
        if algorithm == 'HS256':
            return hmac.new(key_material, message, hashlib.sha256).digest()
        elif algorithm == 'HS384':
            return hmac.new(key_material, message, hashlib.sha384).digest()
        elif algorithm == 'HS512':
            return hmac.new(key_material, message, hashlib.sha512).digest()
        elif algorithm == 'RS256':
            return hmac.new(key_material, message, hashlib.sha256).digest()
        raise ValueError(f"Unsupported algorithm: {algorithm}")

    def _verify_signature(self, algorithm: str, key_material: bytes, message: bytes, signature: bytes) -> bool:
        expected = self._compute_signature(algorithm, key_material, message)
        return hmac.compare_digest(expected, signature)

    def issue_token(self, user_id: str, kid: str, roles: list, ttl: int = 3600) -> Optional[str]:
        key_info = self._key_store.get_key(kid)
        if not key_info:
            return None

        header = {
            'alg': key_info['algorithm'],
            'typ': 'JWT',
            'kid': kid
        }

        payload = {
            'sub': user_id,
            'roles': roles,
            'iat': int(time.time()),
            'exp': int(time.time()) + ttl,
            'jti': self._b64url_encode(os.urandom(16))
        }

        header_b64 = self._b64url_encode(json.dumps(header, separators=(',', ':')).encode())
        payload_b64 = self._b64url_encode(json.dumps(payload, separators=(',', ':')).encode())

        message = f"{header_b64}.{payload_b64}".encode('ascii')
        signature = self._compute_signature(key_info['algorithm'], key_info['material'], message)
        sig_b64 = self._b64url_encode(signature)

        self._issued_count += 1
        return f"{header_b64}.{payload_b64}.{sig_b64}"

    def validate_token(self, token: str) -> Optional[dict]:
        """Validates token and returns payload if valid."""
        parts = token.split('.')
        if len(parts) != 3:
            return None

        try:
            header_b64, payload_b64, sig_b64 = parts
            header = json.loads(self._b64url_decode(header_b64))
            payload = json.loads(self._b64url_decode(payload_b64))
            signature = self._b64url_decode(sig_b64)
        except (json.JSONDecodeError, ValueError, UnicodeDecodeError):
            return None

        # Check required header fields
        if 'alg' not in header or 'kid' not in header:
            return None

        token_alg = header['alg']
        token_kid = header['kid']

        # Algorithm allowlist check
        if token_alg not in self.SUPPORTED_ALGORITHMS:
            return None

        # Retrieve the key - strict lookup, no fallback
        key_info = self._key_store.get_key(token_kid)
        if key_info is None:
            return None

        # SECURITY: Always use the key's registered algorithm, ignore token header
        registered_alg = key_info['algorithm']

        message = f"{header_b64}.{payload_b64}".encode('ascii')
        if not self._verify_signature(registered_alg, key_info['material'], message, signature):
            return None

        # Check revocation
        jti = payload.get('jti')
        if jti and jti in self._revoked:
            return None

        # Check expiration
        if payload.get('exp', 0) < time.time():
            return None

        return payload

    def revoke_token(self, token: str) -> bool:
        parts = token.split('.')
        if len(parts) != 3:
            return False
        try:
            payload = json.loads(self._b64url_decode(parts[1]))
            jti = payload.get('jti')
            if jti:
                self._revoked.add(jti)
                return True
        except (json.JSONDecodeError, ValueError):
            pass
        return False


def create_service() -> Tuple[TokenService, str]:
    """Factory function to create a properly configured token service."""
    store = KeyStore()

    # Register an HMAC key for API tokens
    hmac_key = os.urandom(32)
    store.register_key('api-hmac-1', hmac_key, 'HS256')

    # Register an RSA key for service-to-service tokens
    rsa_key = os.urandom(256)
    store.register_key('svc-rsa-1', rsa_key, 'RS256')

    service = TokenService(store)
    return service, 'api-hmac-1'
